const crypto = require('crypto');

function hashBlock(data) {
  return crypto.createHash('sha256').update(data).digest('hex');
}

function buildMerkleTree(blocks) {
  let level = blocks.map(hashBlock);
  const tree = [level];

  while (level.length > 1) {
    const nextLevel = [];
    for (let i = 0; i < level.length; i += 2) {
      const left = level[i];
      const right = level[i + 1] || left; // duplicate the last hash on an odd count
      nextLevel.push(hashBlock(left + right));
    }
    level = nextLevel;
    tree.push(level);
  }

  return tree; // tree[tree.length - 1][0] is the root hash
}

const blocks = ['user:1001', 'user:1002', 'user:1003', 'user:1004'];
const tree = buildMerkleTree(blocks);
console.log('Root hash:', tree[tree.length - 1][0]);

