function findDivergentLeaf(treeA, treeB) {
  const topA = treeA[treeA.length - 1][0];
  const topB = treeB[treeB.length - 1][0];
  if (topA === topB) return null; // roots match, nothing to repair

  let level = treeA.length - 1;
  let index = 0;

  while (level > 0) {
    const leftIndex = index * 2;
    const rightIndex = leftIndex + 1;
    const leftMatches = treeA[level - 1][leftIndex] === treeB[level - 1][leftIndex];
    index = leftMatches ? rightIndex : leftIndex;
    level -= 1;
  }

  return index; // index of the one leaf block that actually differs
}

